export type OtpLocale = 'ar' | 'en';

export interface OtpMessage {
  /** E.164 with leading "+", e.g. +201012345678. */
  phone: string;
  /** The one-time code generated by Supabase Auth. */
  code: string;
  locale: OtpLocale;
}

/** Transactional (non-OTP) WhatsApp notices. Each kind maps to one pre-approved template on Cloud API. */
export const NOTICE_KINDS = ['consent_invite', 'child_claim', 'consent_granted', 'consent_withdrawn'] as const;
export type NoticeKind = (typeof NOTICE_KINDS)[number];

export interface NoticeMessage {
  /** E.164 with leading "+". */
  phone: string;
  kind: NoticeKind;
  locale: OtpLocale;
  /** Fully rendered text for adapters that send free-form messages (console, open-wa). */
  text: string;
  /** Ordered template variables ({{1}}, {{2}}...) for template-based adapters (WhatsApp Cloud). */
  params: string[];
}

/** Delivers a one-time code (or a transactional notice) to a phone. Implementations must never log codes outside dev. */
export interface OtpSender {
  readonly name: string;
  send(message: OtpMessage): Promise<void>;
  sendNotice(notice: NoticeMessage): Promise<void>;
}

/** What the consent flows need from the WhatsApp layer. The OTP adapters implement it; no second set of adapters. */
export type ConsentMessenger = Pick<OtpSender, 'name' | 'sendNotice'>;

export type OtpSendErrorKind = 'config' | 'network' | 'upstream';

export class OtpSendError extends Error {
  constructor(
    public readonly kind: OtpSendErrorKind,
    message: string,
    public readonly status?: number,
  ) {
    super(message);
    this.name = 'OtpSendError';
  }
}
